let stock = 1;
let seq = 0;

function reset(next) {
  stock = next == null ? 1 : next;
  seq = 0;
}

function settleConcurrent(reserves) {
  const seen = stock;
  const accepted = [];
  let left = seen;
  for (const r of reserves) {
    // Remaining stock, not the pre-loop snapshot — concurrent acquires serialize.
    if (left >= r.qty) {
      accepted.push(r.id);
      left -= r.qty;
    }
  }
  stock = left;
  seq += 1;
  return { accepted: accepted, stock: stock, seq: seq };
}

